// Add an element of type T on top of this stack
public void push(T element) {
  // Create a new node for an element of T
  Node<T> temp = new Node<>(element);
  temp.next = top;
                         // Link it to the top of the stack
  top = temp;
                         // The new node becomes the top node
  count++;
                         // Increment the count of elements
}

